	dockerCmdPattern := `docker run.*-e TAVILY_API_KEY.*ghcr\.io/github/gh-aw-mcpg`
	assert.Regexp(t, dockerCmdPattern, yamlStr,
		"Docker command should include -e TAVILY_API_KEY before the container image")
}

